-- ========================================================================
-- Staff Directory — Full Staff Seed (generated by dev_generate_seed_all.py)
-- Single file combining:
--   1. The 7 reference people (dev_seed_people_block.sql) with their tuned
--      lifecycle/tenure/manager data.
--   2. The 193-employee roster from staff-export-2026-08-05.csv that are NOT
--      the reference people, so their tuned lifecycle data stays intact.
--
-- Employee number + work_mode columns must exist (module upgraded):
--   ./venv/bin/python ./odoo-bin -c ./white_clone.conf -d white_clone_db_v2 \
--       -u hr_staff_directory --stop-after-init
--
-- Run (all-or-nothing; single transaction):
--   psql -U odoo_dev -h localhost -d white_clone_db_v2 -f dev_seed.sql
-- ========================================================================

\set ON_ERROR_STOP on

BEGIN;

-- ── Guard: abort if any seed barcode already exists ───────────────────────
DO $$
BEGIN
